"""Labelled evaluation dataset (JSON or CSV). Human-annotated; nothing here is generated by the system under test."""
from __future__ import annotations

import csv
import json
from pathlib import Path
from typing import Literal

from pydantic import BaseModel, Field, field_validator


class EvidenceRef(BaseModel):
    """A gold passage location: document file name + page numbers (1-based)."""
    document: str
    pages: list[int] = Field(default_factory=list)


class ExpectedClaim(BaseModel):
    text: str
    label: Literal["SUPPORTED", "CONTRADICTED", "INSUFFICIENT"]


class EvalQuestion(BaseModel):
    id: str
    question: str
    answerability: Literal["full", "partial", "unanswerable", "conflicting"]
    query_type: Literal["SIMPLE", "COMPLEX"]
    reference_answer: str = ""
    key_facts: list[str] = Field(default_factory=list, description="Short strings a correct answer must contain")
    reference_sub_questions: list[str] = Field(default_factory=list)
    relevant_evidence: list[EvidenceRef] = Field(default_factory=list)
    expected_citations: list[EvidenceRef] = Field(default_factory=list)
    expected_claims: list[ExpectedClaim] = Field(default_factory=list)
    notes: str = ""
    illustrative: bool = False  # True = example row, must not be reported as a result

    @field_validator("key_facts", "reference_sub_questions", mode="before")
    @classmethod
    def _none_to_list(cls, v):
        return v or []

    @property
    def should_abstain(self) -> bool:
        return self.answerability == "unanswerable"


_LIST_FIELDS = ("key_facts", "reference_sub_questions", "relevant_evidence", "expected_citations", "expected_claims")


def load_dataset(path: str | Path, include_illustrative: bool = False) -> list[EvalQuestion]:
    path = Path(path)
    if path.suffix.lower() == ".csv":
        with path.open(newline="", encoding="utf-8") as f:
            rows = []
            for r in csv.DictReader(f):
                for k in _LIST_FIELDS:  # list/object columns are JSON-encoded in CSV
                    r[k] = json.loads(r[k]) if (r.get(k) or "").strip() else []
                r["illustrative"] = str(r.get("illustrative", "")).strip().lower() in ("1", "true", "yes")
                rows.append(r)
    else:
        raw = json.loads(path.read_text(encoding="utf-8"))
        rows = raw["questions"] if isinstance(raw, dict) else raw
    questions = [EvalQuestion.model_validate(r) for r in rows]
    ids = [q.id for q in questions]
    if len(ids) != len(set(ids)):
        raise ValueError("Duplicate question ids in dataset")
    return questions if include_illustrative else [q for q in questions if not q.illustrative]


# ---------------------------------------------------------------------------------------------- labelled claims
class LabelledClaim(BaseModel):
    """One human-labelled (evidence, claim) pair for evaluating / calibrating the NLI verifier."""
    claim: str
    evidence: list[str] = Field(description="evidence passages (premises); in CSV separate them with ' || '")
    gold: Literal["SUPPORTED", "CONTRADICTED", "INSUFFICIENT"]
    system_label: str | None = None  # present in files exported by run_eval.py
    id: str = ""
    illustrative: bool = False


def load_labelled_claims(path: str | Path, include_illustrative: bool = False) -> list[LabelledClaim]:
    """JSONL/JSON: {claim, evidence, label}. CSV: columns claim, evidence, label | human_label (+ system_label)."""
    path = Path(path)
    if path.suffix.lower() == ".csv":
        with path.open(newline="", encoding="utf-8") as f:
            rows = list(csv.DictReader(f))
    elif path.suffix.lower() == ".jsonl":
        rows = [json.loads(ln) for ln in path.read_text(encoding="utf-8").splitlines() if ln.strip()]
    else:
        raw = json.loads(path.read_text(encoding="utf-8"))
        rows = raw["claims"] if isinstance(raw, dict) else raw
    out: list[LabelledClaim] = []
    for i, r in enumerate(rows):
        gold = (r.get("label") or r.get("human_label") or "").strip().upper()
        if not gold:  # un-annotated row in an export: skip, never guess a label
            continue
        ev = r.get("evidence", "")
        ev = ev if isinstance(ev, list) else [p.strip() for p in str(ev).split(" || ") if p.strip()]
        ill = r.get("illustrative", False)
        out.append(LabelledClaim(
            claim=r["claim"], evidence=ev, gold=gold, id=str(r.get("id") or r.get("question_id") or i),
            system_label=(r.get("system_label") or None),
            illustrative=ill if isinstance(ill, bool) else str(ill).lower() in ("1", "true", "yes"),
        ))
    return out if include_illustrative else [c for c in out if not c.illustrative]
